const fs = require('node:fs');
const V = (m) => { console.error('W2_SEM1_NOT_CHECKED_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('W2_SEM1_NOT_CHECKED_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const path = 'packages/mps-lu/src/domain/AssessmentFinding.ts';
  let src;
  try { src = fs.readFileSync(path, 'utf8'); } catch (e) { H('cannot read ' + path + ': ' + (e && e.message)); }
  const hasNotChecked = /risk_level\s*:\s*[^;]*"NOT_CHECKED"/.test(src);
  if (!hasNotChecked) V('AssessmentFinding.risk_level does not admit "NOT_CHECKED" yet in ' + path);
  console.log('W2_SEM1_NOT_CHECKED_OK: AssessmentFinding.risk_level admits "NOT_CHECKED"');
} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

const fs = require('node:fs');
const V = (m) => { console.error('W2_RULE_VERSION_2_VIOLATION: ' + m); process.exit(1); };
const H = (m) => { console.error('W2_RULE_VERSION_2_HARNESS_ERROR: ' + m); process.exit(2); };
try {
  const path = 'packages/mps-lu/src/rules/LURuleEngine.ts';
  let src;
  try { src = fs.readFileSync(path, 'utf8'); } catch (e) { H('cannot read ' + path + ': ' + (e && e.message)); }
  const ruleIds = ['LU-WATER-001','LU-EBH-001','LU-PROTECTED-001','LU-NATURA2000-001','LU-WATERPROTECTION-001'];
  const missing = ruleIds.filter((id) => {
    const re = new RegExp('rule_id:\\s*"' + id + '"[\\s\\S]{0,80}?rule_version:\\s*"2\\.0"|rule_version:\\s*"2\\.0"[\\s\\S]{0,80}?rule_id:\\s*"' + id + '"');
    return !re.test(src);
  });
  if (missing.length > 0) V('the following governed rules are not yet at rule_version "2.0": ' + missing.join(', '));
  console.log('W2_RULE_VERSION_2_OK: all five layer-based governed rules are at rule_version "2.0"');
} catch (e) { H('unexpected: ' + (e && e.stack ? e.stack : e)); }

const cp = require('node:child_process');
const winx = process.platform === 'win32';
const env = { ...process.env, DATABASE_URL: process.env.DATABASE_URL || 'postgresql://localhost:5432/devgov_dummy' };
const gen = cp.spawnSync(winx ? 'npx.cmd' : 'npx', ['prisma', 'generate'], { env, encoding: 'utf8', shell: winx, timeout: 240000 });
if (gen.status !== 0) { console.error('W2_LAYER_ISOLATION_HARNESS_ERROR: prisma generate failed: ' + ((gen.stderr||'')+(gen.stdout||''))); process.exit(2); }
const test = cp.spawnSync(winx ? 'npx.cmd' : 'npx', ['vitest', 'run', 'packages/spatial-provider-postgis/tests/SpatialProviderPostGISLayerIsolation.test.ts', '--testTimeout=8000'], { env, encoding: 'utf8', shell: winx, timeout: 60000, stdio: 'inherit' });
process.exit(test.status === 0 ? 0 : 1);

